def seed_resorts(apps, schema_editor):
    Resort = apps.get_model("core", "Resort")
    for r in Resort.objects.all():
        data = RESORT_SEED.get(r.name.strip().lower())
        if not data:
            continue
        photo, text = data
        changed = []
        if photo and not r.photo_url:
            r.photo_url = photo; changed.append("photo_url")
        if text and not r.highlight:
            r.highlight = text; changed.append("highlight")
        if changed:
            r.save(update_fields=changed)


